using System;
using System.Globalization;

namespace SpaceKatMonitor
{
    public struct CubePose
    {
        public double X, Y, Z;
        public double Rx, Ry, Rz;
    }

    /// <summary>
    /// Integrates six controller deflections into an on-screen pose only.
    /// No desktop input or device output is generated by this model.
    /// </summary>
    public sealed class CubeMotionModel
    {
        public const int DeadZone = 12;
        public const double SampleTimeoutSeconds = 0.25;
        public const double MaximumStepSeconds = 0.05;
        public const double TranslationSpeed = 0.9;
        public const double RotationSpeedDegrees = 80;
        public const double TranslationLimit = 1.05;

        private readonly double[] input = new double[6];
        private CubePose pose;
        private bool hasSample;
        private double lastSampleSeconds = Double.NaN;
        private double lastStepSeconds = Double.NaN;

        public CubePose Pose { get { return pose; } }
        public bool HasData { get; private set; }
        public bool IsInputFresh { get; private set; }

        public void SetInput(short[] axes, bool hasData, double nowSeconds)
        {
            if (!hasData || axes == null || axes.Length < 6)
            {
                ClearInput();
                HasData = false;
                return;
            }
            if (!ValidTime(nowSeconds) ||
                (!Double.IsNaN(lastStepSeconds) && nowSeconds < lastStepSeconds) ||
                (hasSample && nowSeconds < lastSampleSeconds))
            {
                ClearInput();
                return;
            }

            // Complete the previous sample's small elapsed interval before
            // applying this one. Render rate does not determine movement speed.
            Advance(nowSeconds);
            for (int i = 0; i < 6; i++) input[i] = Normalize(axes[i]);
            lastSampleSeconds = nowSeconds;
            hasSample = true;
            HasData = true;
            IsInputFresh = true;
        }

        public void Advance(double nowSeconds)
        {
            if (!ValidTime(nowSeconds) ||
                (!Double.IsNaN(lastStepSeconds) && nowSeconds < lastStepSeconds) ||
                (hasSample && nowSeconds < lastSampleSeconds))
            {
                ClearInput();
                return;
            }
            if (Double.IsNaN(lastStepSeconds))
            {
                lastStepSeconds = nowSeconds;
                return;
            }
            double elapsed = Math.Min(nowSeconds - lastStepSeconds, MaximumStepSeconds);
            lastStepSeconds = nowSeconds;
            IsInputFresh = hasSample && nowSeconds - lastSampleSeconds <= SampleTimeoutSeconds;
            if (!IsInputFresh)
            {
                hasSample = false;
                Array.Clear(input, 0, input.Length);
                return;
            }
            if (elapsed <= 0) return;
            pose.X = Bounded(pose.X + input[0] * TranslationSpeed * elapsed);
            pose.Y = Bounded(pose.Y + input[1] * TranslationSpeed * elapsed);
            pose.Z = Bounded(pose.Z + input[2] * TranslationSpeed * elapsed);
            pose.Rx = Wrapped(pose.Rx + input[3] * RotationSpeedDegrees * elapsed);
            pose.Ry = Wrapped(pose.Ry + input[4] * RotationSpeedDegrees * elapsed);
            pose.Rz = Wrapped(pose.Rz + input[5] * RotationSpeedDegrees * elapsed);
        }

        public void ResetView()
        {
            pose = new CubePose();
            HasData = false;
            ClearInput();
        }

        public string GetSnapshot()
        {
            return "CubeHasData=" + HasData + "\r\nCubeInputFresh=" + IsInputFresh +
                "\r\nCubePosition=" + Format(pose.X) + "," + Format(pose.Y) + "," + Format(pose.Z) +
                "\r\nCubeRotationDegrees=" + Format(pose.Rx) + "," + Format(pose.Ry) + "," + Format(pose.Rz) + "\r\n";
        }

        private void ClearInput()
        {
            hasSample = false;
            IsInputFresh = false;
            lastSampleSeconds = Double.NaN;
            lastStepSeconds = Double.NaN;
            Array.Clear(input, 0, input.Length);
        }

        private static double Normalize(short value)
        {
            int clipped = Math.Max(-512, Math.Min(512, (int)value));
            int magnitude = Math.Abs(clipped);
            return magnitude <= DeadZone ? 0 : Math.Sign(clipped) * (magnitude - DeadZone) / (512.0 - DeadZone);
        }

        private static double Bounded(double value)
        {
            return Math.Max(-TranslationLimit, Math.Min(TranslationLimit, value));
        }

        private static double Wrapped(double degrees)
        {
            degrees %= 360;
            if (degrees > 180) degrees -= 360;
            if (degrees < -180) degrees += 360;
            return degrees;
        }

        private static bool ValidTime(double value)
        {
            return !Double.IsNaN(value) && !Double.IsInfinity(value) && value >= 0;
        }

        private static string Format(double value)
        {
            return value.ToString("0.000", CultureInfo.InvariantCulture);
        }
    }
}
